        "元，亨，利，贞：《正义》：“《子夏传》云：‘元，始也；亨，通也；利，和也；贞，正也。’言此卦之德，有纯阳之性，自然能以阳气始生万物，而得元始、亨通，能使物性和谐各有其利，又能使物坚固贞正得终。”案，对这四字的解释，旧注颇多异议，以《子夏传》“四德”说较为通行，故《正义》、《集解》均取其说。又，《彖传》及《文言》发挥“四德”之义最为详尽，观后文可知。"
