        "①用九：这是指明《周易》哲学以“变”为主的一方面特点。《易》筮过程中，凡筮得阳爻，其数或“七”、或“九”，“九”可变，“七”不变，故《周易》筮法原则是阳爻用“九”不用“七”，意即占其“变爻”；若筮得六爻均“九”时，即以“用九”辞为占。《本义》：“用九，言凡筮得阳爻者，皆用九，而不用七。盖诸卦百九十二阳爻之通例也。以此卦纯阳居首，故于此发之。而圣人因系之辞，使遇此卦而六爻皆变者即此占之。”",
