    "overview": [
      "《屯》卦喻示事物初生之际的情状，义在阐明“初创艰难”。卦辞既言此时可致亨通，又谓利于守正、宜“建侯”广资辅助，表露了作者哲理浓厚的观点：认为创物虽艰难，若能把握正确的规律，前景必将充满光明。卦中六爻，通过不同的物象，揭示处“屯”之道：初“盘桓”，以居正不出为利；二“屯邅”，似女子“守贞待字”则宜；三“即鹿”，当退不当进；四“求婚”，亲下获吉；五“初创”局面将通，但不可疏忽，须守正防凶；上虽“泣血”，但大势已通，必将化忧为喜。综言之，六爻均围绕物之“初生”、时之“草创”，明其吉凶利咎，大旨无不强调居正慎行。从哲学内涵分析，全卦所明“初生”、“艰难”的本旨，是勉励人沿着“草创”之时的发展趋势，不断开拓、进取，以求得“元亨”为最终目的。《大象传》申言“君子以经纶”，即体现“奋发图治”、处“屯”求通的精神。《宋书·谢灵运传》所谓“国屯难而思抚”，正与此义合，可见，《屯》卦的积极意义，是以辩证的哲学观点，指出“初生”事物的发展前景，展示“君子有为之时”开“屯”致“通”的途径。"
    ],
