        "①屯：音zhūn，卦名，下震（☳）上坎（☵），象征“初生”。案，“屯”，甲金文作“〔屯甲骨字形〕”（见罗振玉《殷墟书契后编》）、“〔屯颂壶字形〕”（颂壶文，见罗振玉《三代吉金文存》）、“〔屯颂鼎字形〕”（颂鼎文，同上），均像植物种子萌生、破土而出之形；《说文》曰：“屯，难也，象艸木之初生，屯然而难，从屮贯一，一地也，尾曲。”可见，“象艸木之初生”是造字本义；又因物初生而多艰难，遂引申有“难”义。故《序卦传》谓“屯者，物之始生也”，《彖传》云“刚柔始交而难生”，并合“屯”义。（卦形以“下震上坎”相重喻“屯”，已具《彖传》、《大象传》所释，见下文注；以后各卦均仿此。）",
