      "《需》卦发“需待”之义，阐明事物在发展过程中当耐心待时的道理。卦辞所谓“亨”、“吉”、“利涉大川”，即是守正需待所致。卦中六爻，不论刚柔，各能容忍守静、敬慎待时，故或吉、或无咎、或化险为夷，皆不呈“凶”象。《折中》引吕祖谦曰：“《需》初九、九五二爻之吉，固不待言。至于余四爻，如二则‘小有言，终吉’，如三之《象》则曰‘敬慎不败’，四之《象》则曰‘顺以听也’，上则曰‘有不速之客三人来，敬之，终吉’。大抵天下之事，若能款曲停待，终是少错。”案《论语·子罕》有一段记载：“子贡曰：‘有美玉于斯，韫匱而藏诸，求善贾沽诸？’子曰：‘沽之哉，沽之哉，我待贾者也。’”刘宝楠《正义》曰：“君子于玉比德。时夫子抱道不仕，故子贡借玉以观夫子藏用之意。‘善贾’，喻贤君也，虽有贤君，亦待聘乃仕，不能枉道以事人也。”孔子所言“待贾”，意谓“藏德待用”；就“待”这一意义看，实与《需》卦“守正待时”之旨相切。"
