        "刚来而得中：此举九二阳刚得中之象，释卦辞“讼，有孚窒惕，中吉”。谓九二以刚来居下卦两阴之间。《正义》：“凡上下二象，在于下象者则称‘来’，故《贲》卦云‘柔来而文刚’，是离下艮上而称‘柔来’。今此云‘刚来而得中’，故知九二也。且凡云‘来’者，皆据异类而来，九二在二阴之中，故称‘来’。”案，孔氏释“刚来”之义，可备参考。",
