      "《小畜》卦旨，揭示事物发展过程中“小畜大”、“阴畜阳”的道理。就畜聚的主体看，是“小”者、“阴”者；就畜聚的程度看，是微小、不过甚。卦辞以“密云不雨”为喻，正是从这两方面指明卦义，强调“阴”只能在适宜的限度内畜聚“阳”，以略施济助为己任，形成浓云而不降雨的情状：这是“小有畜聚”的至美之道。换言之，阴聚阳而不制阳，犹如臣畜君而不损君，于是“小畜”可致“亨通”。李士鉁曰：“《孟子》曰：‘畜君何尤？畜君者，好君也。’臣能畜君，君能从臣，所以亨也。”（《周易学说》引）卦中五阳爻为被畜的对象，六四阴爻为畜阳的主体。下卦三阳不宜被六四所畜，在于阳质尚弱，被“畜”必被制，故初、二能返复、自畜阳刚获“吉”，三躁进被畜遂致“脱辐”、“反目”之灾；上九居“小畜”穷极之际，被“畜”必被损，故以凶设戒；唯九五阳刚中正，与六四如君臣相得，诚信相推，成为“畜”与“被畜”之间最完美的象征。可见，本卦虽以阴为主爻，其大旨还是以“扶阳”为根本归宿，体现了《周易》崇尚阳刚之德的思想。"
