        "①天地交而万物通：天，指下乾；地，指上坤。此据上下卦象，说明天地阴阳交和、万物生养畅通之理。《集解》引何妥曰：“此明天道泰也。夫泰之为道，本以‘通’生万物。若夭气上腾，地气下降，各自闭塞，不能相交，则万物无由得生。明万物生由天地交也。”案，自然现象中，如地气受热上升为云，云气冷却下降为雨，在古人心目中正属“天地交”之理。",
        "上下交而其志同：上，喻君；下，喻臣。此句合前句释卦名“泰”。《集解》引何妥曰：“此明人*泰也。上之与下，犹君之与臣，君臣相交感，乃可以济养万民也。”",
        "内阳而外阴，内健而外顺，内君子而外小人：内、外，指内卦、外卦；阳、健、君子，指三阳爻；阴、顺、小人，指三阴爻。此三句以阴阳爻的居位特点，释卦辞“小往大来”。《集解》引何妥曰：“顺而阴居外，故曰‘小往’；健而阳在内，故曰‘大来’。”又引崔憬曰：“阳为君子，在内健于行事；阴为小人，在外顺以听命。”",
        "君子道长，小人道消：此总结前三句的喻意，并释卦辞“吉，亨”，说明“泰”之时阳息阴消，利于“君子”不利于“小人”。《集解》引《九家易》曰：“谓阳息而升，阴消而降也。”"
