      "translation": [
        "《彖传》说：“通泰，柔小者往外、刚大者来内，吉祥，亨通。”这是表明天地阴阳交合、万物的生养之道畅通，君臣上下交合、人们的思想意识协同。此时阳者居内、阴者居外，刚健者居内、柔弱者居外，君子居内、小人居外：于是君子之道盛昌，小人之道消亡。"
      ]
