        "①天地交，泰：释《泰》卦下乾为天、上坤为地之象。《集解》引荀爽曰：“坤气上升，以成天道；乾气下降，以成地道。天地二气若时不交，则为闭塞；今既相交，乃通泰。”",
        "后以财成天地之道：后，《尔雅·释诂》：“君也”；财，《释文》引荀爽本作“裁”，《集解》引郑玄曰“节也”，《本义》“财，裁同”，犹言裁节调理；夭地之道，即夭地相交之道。此调“通泰”之时，必须善为裁节调理，不使溢“通”失节，才能成就“天地相交”之道。案，《集解》引虞翻注，主张“财”即谓“财用”，指出“守位以人，聚人以财，故曰成天地之道”；惠栋《周易述》发挥虞义曰：“言后资财用以成教，赞天地之化育”；近人黄元炳《易学探源经传解》也认为：“人以财交通，即以成夭地交应之道。”此均可备参考。",
        "辅相天地之宜：相，读xiàng，“辅相”犹言辅助赞勉，与前句“财成”对文；天地之宜，即天地化生之宜。此谓“通泰”之时，必须多加扶持，不断赞勉促进天地化生之宜。辞意含有不可因“泰”自逸的微旨。",
        "以左右民：左右，即“佐佑”，犹言“保佑”。此句合前两句，说明“君主”观《泰》卦之象，悟知处“泰”不可安逸无事，应当调节成就“天地之道”，辅助赞勉“天地之宜”，使上下交通、治国保民，才能长获“通泰”。《王注》：“泰者，物大通之时也。上下大通，则物失其节，故‘财成’而‘辅相’，以左右民也。”"
