        "①天与火，同人：与，作动词，犹“亲”，《管子·精言》“诸侯之所与也”注谓：“与，亲也”，此处犹言“亲和”。这两句以天体在上、火性亦炎上，两相亲和，释《同人》上乾为天、下离为火之象。《正义》：“天体在上，火又炎上，取其性同，故云‘夭与火，同人。’”案，《集解》引《九家易》曰：“谓乾舍于离，同而为日，天日同明、以照于下，君子则之、上下同心，故曰‘同人’”；又引苟爽曰：“乾舍于离，相与同居，故曰‘同人’也。”两说各从不同的角度分析卦象，并可存备参考。",
