        "忒：音恰，《集解》引虞翻曰：“差迭也”，犹言“差错”。",
        "豫之时义大矣哉：这是《彖传》作者对本卦含义深广的叹美之辞。《正义》：“叹美为‘豫’之善，言于逸豫之时，其义大矣，此叹卦也。”案，《彖传》凡叹“大矣哉”者，共有十二卦。《正义》又曰：“凡言不尽意者，不可烦文其说，且叹之以示情，使后生思其余蕴，得意而忘言也。然叹卦有三体：一直叹‘时’，如‘大过之时大矣哉’之例是也；二叹‘时’并‘用’，如‘险之时用大矣哉’之例是也；三叹‘时’并‘义’，‘豫之时义大矣哉’之例是也。”《周易玩辞》亦曰：“《豫》、《随》、《遁》、《斯》、《旅》，皆若浅事而有深意，故曰‘时义大矣哉’，欲人之思之也；《坎》、《睽》、《赛》，皆非美事，而圣人有时而用之，故曰‘时用大矣哉’，欲人之别之者；《颐》、《大过》、《解》、《革》，皆大事大变也，故曰‘时大矣哉’，欲人之谨之也。”上说分析《彖传》叹美卦义的特点，并可参考。"
