        "先甲三日，后甲三日：甲，“天干”数之首，其序为甲、乙、丙、丁、戊、己、庚、辛、壬、癸；在此十数中，“甲”富有“终而复始”的涵义，故取“甲日”作为“转化”弊乱、再为治理的象征，即《豪传》“终则有始”之旨。这两句言先后“甲”三日，语多省略，大意指预先深虑“治蛊”前的事状，详为辨析，引为鉴戒；再推求“治蛊”后必将出现的事态，制定措施，谨慎治理：这样，才能根治蛊乱，获得“元亨”的前景。《程传》曰：“甲，数之首，事之始也”，“治蛊之道，当思虑其先后三日，盖推原先后，为救弊可久之道。先甲，谓先于此，究其所以然也；后甲，谓后于此，虑其将然也。一日、二日至于三日，言虑之深，推之远也。”"
