    "overview": [
      "《噬嗑》卦以口中“啮合”食物为喻，阐发“施用刑法”之义。卦辞谓“亨，利用狱”，已经明示顺从正确的规律“治狱”可致亨通的卦旨。六爻之象，以初、上两阳喻触刑受罚，前者初犯能改获“无咎”，后者积罪深重致“凶”，均含深戒；二至五四爻，喻施刑于人，其中六二以柔乘刚，六三、六五阴处阳位，九四阳处阴位，均流露着刚柔相济的“治狱”之道。《折中》引李过曰：“五，君位也，为治狱之主；四，大臣位也，为治狱之卿；三、二，又其下也，为治狱之吏。”然而，四爻之位虽有高低之别，其“治狱”过程却普遍存在着“咎”、“吝”、“艰”、“厉”的情状，此中似乎表明《周易》作者深知“治狱”之艰难。朱熹指出：“大抵才是治人，彼必为敌，不是易事”，“须以艰难正固处之。”（《朱子语类》）至于最能体现全卦大义的，当属柔中居尊的六五：其“德”本于“文明”，犹如用刑期于无刑；其用立于刚严，犹如雷震奋发声威。《大象传》“明罚敕法”的义理，正见于此。马振彪认为：“圣世彰善瘅恶，明威并用，道在雷厉风行。水懦弱，民狎而玩之，故多死焉；火猛烈，民望而畏之，故鲜死焉。制刑之法，取火雷为象，盖有道矣。然以柔中为主，仍不失辟以止辟，刑期无刑之意。老子善用柔，经言‘民不畏死，奈何以死惧之？’盖得柔中之道矣。”（《周易学说》）此论深推“柔中”的寓意，颇能发显本卦哲理。"
    ],
