    "name": "无妄",
    "volume": "upper",
    "overview": [
      "《无妄》卦大义，主于处事“不妄为”。卦辞从正反面揭示其旨：先称万物“无妄”之时必然至为亨通，利于守正；再戒违背正道者此时将遭祸患，动辄失利。六爻情状，皆呈“不妄为”之象，但吉凶利咎却各不相同：初九起步不妄，往无不吉；六二不贪不妄，安顺获利；六三无所妄为，却飞来横灾；九四以刚守谦，不妄则无害；九五无妄得疾，不治自愈；上九不妄自守，欲行却有祸。人们要问：既然六爻未尝有一爻“妄为”，为何利弊如此悬殊呢？胡炳文曰：“善学《易》者在识‘时’。初曰‘吉’，二曰‘利’，时也；三曰‘灾’，五曰‘疾’，上曰‘眚’，非有妄以致之也，亦时也。初与二皆可往，时当动而动；四‘可贞’，五‘勿药’，上‘行有眚’，时当静而静。”（《周易本义通释》）可见，本卦认为：若欲长保“无妄”，避害就利，凡事动静行止，不能不审时度势。当然，“识时”必须建立在“守正”的基础上；一旦“失正”，则无利可言：此卦辞所明“匪正有眚”之义。朱熹指出：“《无妄》一卦，虽云祸福之来也无常，然自家所守者，不可不利于‘正’。”（《朱子语类》）至于“正”的概念，就古代伦理思想的范畴领会，莫过于遵循“礼”教。孔子曰：“非礼勿视，非礼勿听，非礼勿言，非礼勿动。”（《论语·颜渊》）实与《无妄》卦旨颇可相通。"
    ],
