    "volume": "upper",
    "overview": [
      "《左传》僖公十四年载虢射曰：“皮之不存，毛将安傅？”说明事物往往需要附着于一定的环境。就自然物象而言，太阳依附于天空广照大地，火焰依附于燃料发出光热，是最为显明的事例。《离》卦所示“附丽”之义，正是以火、日为基本喻象。卦辞称“畜养牝牛”可获吉祥，则是强调“附丽”之时必须柔顺守正才能亨通畅达。从六爻的情状分析，二、五获吉在于阴柔居中，守持正道以成“附丽”之美；三、四皆凶，则是阳刚不中不正，或面临穷衰，或虚势“无所容”，均不能遂“附丽”之志；至于初、上两阳，初九处下敬慎、渐能附丽于物，上九“离”道已成、物皆亲附，故两爻并获“无咎”。若以《坎》、《离》两卦互为比较，又可进一步看出，“行险”当以“刚中”为主，“附丽”则以“柔中”为宜：这是两卦适为相反的核心意义。当然，《离》卦的象征喻旨也是十分广泛的，取“人事”为说，不论人的地位尊卑如何，均须附丽于所处的时代、社会；而人与人之间的不同层次，又存在附丽与被附丽的复杂关系：人类的社会结构，于是不可避免地反映出一种特定的组合。《彖传》极称：“重明以丽乎正，乃化成天下。”程颐曰：“天地之中，无无丽之物，在人当审其所丽，丽得其正则能亨也。”“君臣上下，皆有明德，而处中正，可以化成天下，成文明之俗。”（《程传》）这事实上是把《离》卦的哲学意义纳入古代政治思想的范畴中去了。"
    ],
