        "畜牝牛吉：此句专明“附丽”当取柔顺，才能获“吉”，故以“畜牝牛”为喻。《王注》：“柔处于内而履正中，牝之善也；外强而内顺，牛之善也。《离》之为体，以柔顺为主者也，故不可以畜刚猛之物，而吉于畜牝牛也。”"
