    "overview": [
      "人情物理，总是好合不好离，喜聚不喜散。《古诗十九首》“行行重行行，与君生别离；相去万余里，各在天一涯”（《文选》卷二十九）几句，是较有代表性的嗟伤睽违离别的诗歌艺术反映。《睽》卦取名“乖背睽违”，卦旨却在于揭示如何化“睽”为“合”的道理。卦辞谓：“小心处事可获吉祥”，即表明事物虽“睽”，必有可同、可合之处，用柔和细致的方法顺势利导，乖背能消、睽违终合。卦中六爻虽均在“睽”时，但未尝一爻久睽不合。《折中》引冯当可曰：“内卦皆睽而有所待，外卦皆反而有所应：初‘丧马勿逐’，至四‘遇元夫’，而初、四合矣；二委曲以求遇，至五‘往何咎’，而二、五合矣；三‘舆曳’、‘牛掣’，至上‘遇雨’，而三、上合矣。天下之理，固未有终睽也。”可见，诸爻均以“小心”、“委婉”之道，并收“济睽”、“合睽”之功，所谓“委曲巽入则易通也”（《折中》）。从各爻的义理中，可以明显看出《周易》作者对于事物“同”“异”、“睽”“合”辩证关系的认识；《彖传》称“天地睽而其事同也，男女睽而其志通也，万物睽而其事类也”，正阐发这一意义。至于《大象传》所明“求大同存小异”的旨趣，则是对“小心处睽”这一抽象概念的具体发挥，从而使《睽》卦蕴含的“对立统一”的哲学因素进一步显露出应有的色彩。"
    ],
