      "notes": [
        "①睽：音kuí，卦名，下兑（☱）上离（☲），象征“乖背睽违”。《序卦传》：“睽，乖也”；《说文》谓“目不相听”，指两目相背，即“乖违”之意。",
        "小事吉：小，阴柔之称，此处含“小心”之义。凡物相睽，必须以柔顺的方法，小心寻求其中可合之处，才能转“乖睽”为“谐和”；若刚断强合，必难“济睽”。故称“小事吉”。卦中六五以柔处中应刚，正合此象。《集解》引虞翻曰：“小谓五，阴称小，得中应刚故吉。”"
      ],
      "explanation": [
        "“小事吉”之义，有两种说法较为通行。一是认为“小事”指细小之事。如孔颖达《正义》曰：“物情乖异，不可大事。大事谓兴役动众，必须大同之世方可为之；小事谓饮食衣服，不待众力，虽乖而可。”一是认为“小事”指“以柔为事”。如《折中》引何楷曰：“业已睽矣，不可以忿疾之心驱迫之也；惟不为已甚，徐徐转移，此‘合睽’之善术也。故曰‘小事吉’。小事，犹言以柔为事；非大事不吉，而小事吉之谓。”今取后说。"
      ],
