        "①夬：卦名，下乾（☰）上兑（☱），象征“决断”。案，“夬”字之义，谓“决断”、“果决”，此处指“阳刚”对“阴柔”采取决断性的制裁。卦中五阳共决上六一阴，正含此象。《彖传》：“夬，决也，刚决柔也。”《正义》：“夬，决也。此阴消阳息之卦也，阳长至五，五阳共决一阴，故名为‘夬’也。”",
        "扬于王庭：扬，犹言宣布；王庭，《正义》：“百官所在之处”，指君王的法庭。此谓“君子”制裁“小人”应当光明正大地宜扬于“王庭”，以喻“刚决柔”之际“公正无私”的情状。《正义》：“以君子决小人，故可以显然发扬决断之事于王者之庭，示公正而无私隐也。”",
        "孚号有厉：号，号令。此承前句义，说明“君子”决“小人”之时，又须号令众人戒备危险。《程传》：“孚，信之在中，诚意也；号者，命众之辞。君子之道虽长盛，而不敢忘戒备；故至诚以命众，使知尚有危道。虽以此之甚盛，决彼之甚衰，若易而无备，则有不虞之悔；是尚有危理，必有戒惧之心，则无患也。”",
        "告自邑，不利即戎：告自邑，犹言“颁告政令于邑”；即戎，谓兴兵出师。这两句进一步说明“刚决柔”是以“德”制裁，并非以武力取胜。《王注》：“以刚断制，告令可也。告自邑，谓行令于邑也。用刚即戎，尚力取胜也；尚力取胜，物所同疾也。”",
        "利有攸往：此句总结上文，指出处“夬”之时，利于“刚”不利于“柔”，故阳《王注》：“刚德愈长，柔邪愈消，故‘利刚者若能循上述之道而行，必然利有所往。有攸往’，道乃成也。”"
