          "①系于金柅，贞吉：柅，音nǐ，《正义》引马融曰“在车之下，所以止轮令不动者也”，即刹车器。这两句以“金”喻“刚”，“金柅”指九四；谓初六一阴在下，当“遇”之时，处下卦巽风浮躁之体，有“自纵”无归的情状，故须专一系应于九四，长守正固，可获吉祥。《王注》：“金者，坚刚之物；柅者，制动之主：谓九四也。初六处‘遇’之始，以一柔而承五刚，体夫躁质，得遇而通，散而无主，自纵者也。柔之为物，不可以不牵；臣妾之道，不可以不贞，故必系于正应，乃得‘贞吉’也。”",
          "有攸往，见凶，羸豕孚蹢躅：羸豕，羸弱之豕，此处犹言“牝猪”，喻初六；孚，通“浮”，谓“轻浮躁动”；蹢躅，音dí zhú，同“踯躅”，不安静而徘徊之状，《释文》：“蹢，一本作‘躑’”，“躅，本亦作‘䠱’，蹢躅，不静也”。这三句紧承前文，又从反面设戒，说明初六若是急于有所前往，像“牝猪”躁动而“蹢躅”不静，心不专一，必有凶险。此亦前文所谓守“贞”应四之义。《王注》：“若不牵于一，而有攸往，行则唯凶是见矣。羸豕，谓牝豕也。群豕之中，豭强而牝弱，故谓之‘羸豕’也。孚，犹务躁也。夫阴质而躁恣者，羸豕特甚焉。言以不贞之阴，失其所牵，其为淫丑，若‘羸豕’之孚务‘蹢躅’也。”案，焦循认为王弼训“孚”与“浮”通，指出：“王氏以‘孚’为‘务躁’，盖读‘孚’为‘浮’。浮，轻也，谓轻躁也。‘孚’、‘浮’古字通，《释名》‘浮，孚也’是也。‘务’为‘骛’之通借；‘务’、‘骛’《尔雅》皆训‘强’。乱驰为‘骛’，‘骛躁’言其奔驰而轻躁也；下直云‘孚务’，即‘浮骛’也。”（《周易补疏》）又案，《周易举正》引《王注》，“务”正作“骛”，足证焦氏说是也，今从之。"
