          "若号，一握为笑：勿恤，往无咎：号，呼号；一握为笑，一握之间成欢笑。这几句从正面告诫初六，谓其若能呼号九四，四必来应，两者将握手言欢，故勉以“勿恤，往无咎”。《折中》引王宗传日：“初之于四，相信之志，疑乱而不一也。然居萃之时，上下相求，若号焉，四必说而应之，则一握之顷，变号味而为笑乐矣，谓得其所萃也。故戒之日‘勿恤’，又勉之日’往无咎‘。”案，王宗传训“号”为“号味”，则“一握为笑”有“破涕为笑”之意，于义亦通。"
