    "name": "困",
    "volume": "lower",
    "overview": [
      "文天祥《正气歌》热情赞颂了古代为正义而斗争的人们，表现了诗人崇高的民族气节。诗中有两句说道：“时穷节乃见，一一垂丹青。”（《文山先生全集》）表明在困苦穷厄之际，最能检验人的品质。《困》卦大义，正是喻示处“困穷”的道理。卦辞极力说明，只有“君子”才能身当困境、其道亨通，称扬守持正固的“大人”可获吉祥、无咎；并进一步指出，此时凡有所言均难见信于人，因此务须洁身自守，修美己德。《彖传》用“刚掩”两字，揭出导致“困穷”的根本原因是阳刚被掩蔽不能伸展，亦即“君子”被“小人”压抑侵凌。卦中六爻分别展示不同的处“困”情状，其中三阴爻柔暗懦弱，罹困至甚：初六坐困不能自拔，六三困非其所、据非其地，两者难免凶危；惟上六当困极将通之时，能及早悔悟则可解困获吉。三阳爻虽亦在“困”中，但均以阳刚气质而能守正脱困：二、五禀刚中美德，或于贫困艰难之时舍身遂志而获无咎，或以孚诚中正之志转危为安渐脱困境；九四前路受困阻，因深谨缓行也能得遂己愿。可见处“困”之道阴阳有别、因人而异。吴日慎论曰：“困非自己致而时势适逢者，则当守其刚中之德，是谓‘困而不失其所亨’也，其道主于‘贞’；若困由己之柔暗而致者，则当变其所为，以免于困也，其道主于‘悔’。学者深察乎此，则处困之道，异宜而各得矣。”（《折中》引）若细致体味本卦的“象外之旨”，还可以看出作《易》者的一层深切寓旨：困穷有时难以避免，正气却不可一刻消颓。《大象传》称“君子以致命遂志”，正见此意；孔子曰：“三军可夺帅也，匹夫不可夺志也。”（《论语·子罕》）与这一义理也甚为吻合。"
    ],
