    "volume": "lower",
    "overview": [
      "朱熹说：“革，是更革之谓，到这里须尽翻转更变一番”，“须彻底从新铸造一番，非止补苴罅漏而已。”（《朱子语类》）此语揭示了《革》卦所喻“变革”意义的激烈性质。从卦辞的主旨分析，则是集中强调变革取得成功的两大要素：首先，要把握时机，犹如选择亟待转变的“己日”断然推行变革，必能顺畅；其次，要存诚守正，即推行变革者必须遵循正道，以孚诚之心取信于人。以此行革，“元亨”可致，“悔恨”皆消。《彖传》称“汤武革命，顺乎天而应乎人”，正是用史例说明上述两义：“顺天”，则顺合当变之机；“应人”，则行正获人信从。六爻的喻象均围绕卦辞大义申发其旨，展示事物变革初期到末期的发展过程，体现了作者对变革规律的深刻认识：初九阳微位卑，时未可变须固守常制；六二柔中有应，其时将变当断然行革；九三变革小成，不可激进宜慎抚人心；九四以刚处柔，变局将著当力改旧命；九五阳刚中正，“虎变”创制而信德昭彰；上六助成革命，“豹变”立功要安守成果。显然，诸爻分别反映变革过程某一阶段的特征；初爻与上爻始于固守旧规、终于安保新制的义理，又表露出事物全面、彻底更革的“质变”情状。《周易》哲学立足于“变”，《革》卦则是论“变”的典型。尽管诸家《易》说多从政治变革的角度阐述卦旨，但其象征意义实可广为旁通。就文学现象而言，刘勰《文心雕龙》撰立“通变”一篇，论说文学发展的“参伍因革”之道，即与此卦理趣相通。唐代韩愈、柳宗元等人力扫齐梁积弊，推行旨在改革文风的“古文运动”，极力倡扬“惟陈言之务去”、“变浮靡为雅正”，更是“变革”哲理在文学理论上的体现。"
    ],
