        "己日乃孚，元亨，利贞，悔亡：己日，古代以“十干”纪日，“己”正当前五数与后五数之中而交转相变之时，故有“转变”的象征寓意；其后一数“庚”，则有“已变更”之义。卦辞取“己日”为象，说明面临当须“转变”之际果断推行变革，并能够心怀“孚信”，则天下也将以“信”应之；这样就可获“元亨”，利于守“正”，其“悔”必将消亡。朱震《汉上易传》曰：“（己）当读作‘戊己’之‘己’，十日至‘庚’而更；更，革也。”顾炎武《日知录》承之，曰：“天地之化，过中则变。日中则凡月盈则食，故《易》所贵者中。十干则‘戊己’为中，至于‘己’则过中而将变之时矣，故受之以‘庚’；庚者，更也。天下之事当过中而将变之时，然后革而人信之矣。”案，“己”字，阮刻及诸本通作“巳”；《王注》以“即日不孚”训“巳日乃孚”，则王弼读作“已然”之“已”；《集解》引虞翻注，释“己日”曰：“离为日”，盖以“纳甲法”之“离纳己”为说，则虞氏读作“戊己”之“己”。今据虞氏本改（六二爻辞同）。"
