    "name": "鼎",
    "volume": "lower",
    "overview": [
      "鼎，作为烹饪之器，有“养人”的功用；作为“法器”，又是“权力”的象征。《九家易》曰：“鼎者，三足一体，犹三公承天子也。三公，谓调阴阳；鼎，谓调五味。”（《集解》引）可见，《鼎》卦立义，是借烹物化生为熟，譬喻事物调剂成新之理，其中侧重体现行使权力、“经济天下”、“自新新人”的意义：《杂卦传》所谓“《革》去故也，《鼎》取新也”，即明此旨。马振彪指出：“革之大者，无过于迁九鼎之重器，以新一世之耳目；而鼎之为用，又无过于变革其旧者，咸与为新，而成调剂大功。故《鼎》承《革》卦，以相为用。若器主烹饪以养，犹其小焉者也。《大象》括以‘正位凝命’四字，养德养身、治家治国之道，为有天下者所取法，皆不能出其范围。”（《周易学说》）从卦辞的大义看，所称“君子”掌持鼎器至为吉祥，前景亨通，也是立足于强调“去故取新”、法制昌明的宗旨。观卦中六爻，各取鼎器的某一部位或配件为喻，无非说明在一定的环境条件下，任事执权的不同情状。诸爻吉美之占居多，如初六阴柔在下，颠倒鼎脚、清除废物可获“无咎”；九二鼎中有实，谨慎处之、不使充溢可致“吉祥”；九三鼎耳变异、鼎用受碍，若能调和阴阳亦终有吉；至于五、上两爻如金玉之“铉”，则佳美尤甚，前者为一卦掌鼎之主、“利”在守“正”，后者鼎用大成、“大吉，无不利”。全卦惟九四一爻不称职权，“折足”、“覆餗”，是寓诫最为深刻的反面形象。董仲舒引此论曰：“以所任贤，谓之主尊国安；所任非其人，谓之主卑国危：万世必然，无所疑也。其在《易》曰：‘鼎折足，覆公餗。’夫鼎折足者，任非其人也；覆公餗者，国家倾也。是故任非其人而国家得不倾者，自古至今，未尝闻也。”（《春秋繁露·精华篇》）显然，六爻的正反面喻象集中揭示了本卦的核心意义；鼎器功用之所能成，事物新制之所以立，必须依赖多方面的纯正、坚实“力量”的协心撑持；《大象传》盛称“君子”应当端正居位、严守使命，实是对这一义理的绝好阐述。"
    ],
