          "震索索，视矍矍，征凶：索索，《释文》引郑玄曰：“犹‘缩缩’，足不正也”，形容惧极而双足畏缩难行；矍，音jué，“矍矍”，《释文》引郑玄曰“目不正”，即双目旁顾不安之状。此谓上六以阴处“震”之极，惊恐至甚，无所安适，故双足“索索”，两目“矍矍”；以此而“征”，必遭凶险。《王注》：“处《震》之极，极震者也。居震之极，求中未得，故惧而索索，视而矍矍，无所安亲也。已处动极而复征焉，凶其宜也。”",
