    "name": "艮",
    "volume": "lower",
    "overview": [
      "《艮》卦取义于“止”，阐发“抑止”邪欲的道理。《礼记·乐记》云：“奸声乱色，不留聪明；淫乐慝礼，不接心术；惰慢邪辟之气，不设于身体。”所谓“不留”、“不接”、“不设”，正与《艮》卦“抑止”之理相通。卦辞反复申言“艮其背”之旨，正是展示“止邪”的最佳方式是使人“隔绝邪欲”，强调“心不乱”而邪已止的功效。钱锺书引《红楼梦》“风月宝鉴，宜照反面”为喻，指出“反面一照”，“妄动”能“治”（《管锥编》），颇与卦旨妙契。卦中六爻所发的意义，又分别取象于人体各部位，从不同角度揭明“抑止”或得或失的情状。六二如“小腿”当行不得行，九三似“腰部”宜动不能动：并属施止不当之象；初六止于“趾”动之前，六四自止其“身”，六五慎止其“口”，上九敦厚于止：均为施止妥善之象。若深究卦理，还可以发现，“抑止”并非绝对强调“不行”。《彖传》“时止则止，时行则行”，已经道出“行”、“止”间的辩证关系；六五“止其辅”之后导致“言有序”，更是以“止”求“行”的明显象例。因此，本卦尽管主于“止”义，“止”的目的却在于保持正确的“行”，含有“行正”必先“止邪”的微旨。那么，《大象传》言“思不出其位”，无疑是把“抑止”作为“进取”的前提。"
    ],
