    "overview": [
      "《旅》卦专明“行旅”之理。《杂卦传》曰“旅，亲寡”，《序卦传》曰“旅而无所容”；张衡《思玄赋》云“顾羁旅而无友兮，余安能留乎此”：显然，在古人心目中，“羁旅”生涯是充满孤独、愁郁情调的。《周易》作者设此一卦，似乎也正是基于“旅”而难“居”的因素，喻人善处“行旅”之道。卦辞所谓“小亨”、“贞吉”，表明“行旅”既须守正，又当以柔顺持中为本。视其六爻，凡阴柔中顺皆吉，但以卑屈者设反面之戒；凡阳刚高亢皆危，而以穷骄者最呈凶象。范仲淹曰：“夫旅人之志，卑则自辱，高则见嫉；能执其中，可谓智矣。是故初‘琐琐’而四‘不快’者，以其处二体之下，卑以自辱者也；三‘焚次’而上‘焚巢’者，以其据二体之上，高而见嫉者也；二‘怀资’而五‘誉命’，柔而不失其中者也。”（《范文正公集》）此说从六爻位次析其吉凶，颇见理致。当然，本卦大旨并非拘于狭义的“行旅”，略推之，所谓“诸侯之寄寓，大夫之去乱，圣贤之周游皆是”（梁寅《周易参义》）；广言之，李白称：“天地者，万物之逆旅”（《春夜宴桃李园序》），则将人生、万物均视为“行旅”之事，此中含有明显的消极思想，但与《旅》卦的“象外之旨”亦略有可通之处。《彖传》极言“旅之时义大矣哉”，于上述之例似能见其一斑。"
    ],
