        "先王以享于帝立庙：这是说明“先王”观“风行水上”之象，悟知“散中有聚”之理，故“享帝”、“立庙”以归系天下人心。《程传》：“收合人心，无如宗庙，祭祀之报，出于其心。故‘享帝’、‘立庙’，人心之所归也。紧人心，合离散之道，无大于此。”"
