        "其道穷也：此以上六穷极于上之象，释卦辞“苦节不可，贞”。《集解》引虞翻曰：“位极于上，乘阳，故穷也。”",
        "说以行险，当位以节，中正以通：说，即“悦”，指下兑为“悦”；险，指上坎为险；当位，指四、五两爻阴阳得位；中正，谓五。此又举上下象及四、五爻象，进一步申明“节制”必须不违“悦”、适当而不过“中”之理。《集解》引虞翻曰：“兑说，坎险”，“中正谓五”。《正义》：“更就二体及四五当位重释行节得亨之义，以明’苦节‘之穷也。”",
