        "小过：卦名，下艮（☶）上震（☳），象征“小有过越”。案，“小过”之义，与“大过”可相对照。此卦外四阴超过中二阳，阴称“小”，故谓“小过”；其寓理又含小事过越、小有过越等义。《程传》：“小者过其常也，盖为小者过；又为小事过，又为过之小。”《本义》：“小谓阴也，为卦四阴在外，二阳在内，阴多于阳，小者过也。”",
