        "柔得中，是以小事吉也；刚失位而不中，是以不可大事也：柔，指六二、六五；刚，指九三、九四。这四句用卦中柔爻、刚爻的居位特点，释卦辞“可小事，不可大事”。《正义》：“此就六二、六五以柔居中，九四失位不中、九三得位不中，释‘可小事，不可大事’之义。柔顺之人，惟能行小事；柔而得中，是行小中时，故日‘小事吉’也。刚健之人，乃能行大事；失位不中，是行大不中时，故日‘不可大事’也。”",
