      "notes": [
        "既济：卦名，下离（☲）上坎（☵），象征“事已成”。案，“既济”词义，是用渡水已竟表示“事已成”。《释文》引郑玄曰：“既，已也，尽也；济，度也。”《正义》：“济者，济渡之名；既者，皆尽之称。万事皆济，故以‘既济’为名。”",
        "亨小，利贞：亨小，犹言“小亨”，“小”指阴柔。此谓“既济”之时，不但大者亨通，小者也均获亨通，故卦中六爻皆得位；而此时又宜于守正，故曰“利贞”。《正义》：“既万事皆济，若小者不通，则有所未济，故曰‘既济，亨小’也。小者尚亨，何况于大？则大小刚柔各当其位，皆得其所。当此之时，非正不利，故曰‘利贞’也。”",
        "初吉终乱：这是诫勉“事成”之后应慎为守成，否则将致危乱。《正义》：“人皆不能居安思危，慎终如始，故戒以今日‘既济’之初，虽皆获吉；若不进德修业，至于终极，则危乱及之。”案，尚先生训“既济”为“终止”，曰：“其在既济之初，上下得所，民物咸宜，故‘初吉’；然《易》之道以变通为贵，无或休息，止而终于是，则《易》道穷矣，故‘终乱’。”可备一说。"
      ],
      "explanation": [
        "卦辞“既济，亨小，利贞”，《集解》引虞翻注，以“亨小”为句。故《释文》出“亨小”，并谓：“绝句，以‘小’连‘利贞’者非。”但后人对此又有多种不同看法，兹举三说以备参考：一、朱熹以为“亨小，当为‘小亨’”，并说《彖传》“既济，亨”之“亨”上当有“小”字（《本义》）。二、毛奇龄以为当读作“既济亨，小利贞”（《仲氏易》）。三、俞樾谓“小”字为衍文，其理由是《彖传》云“既济，亨，小者亨也；利贞，刚柔正而位当也”，则卦辞本无”小“字，并说：“其作‘亨小’者，涉《未济》‘亨，小狐汔济’之文而衍耳”（《群经平议》）。尚先生赞成俞氏说，认为“征之《彖传》，其为衍文无疑”（《尚氏学》）。今查帛书《周易》，亦有“小”字；可知此字若为衍文，则西汉人抄写帛书所据之本已衍。"
      ],
